#!/usr/bin/env python3
"""Scoring harness for the Phase 15 WSP batteries. Runs on the Thor GPU box
(the model under test is never needed on the builder's machine).

Usage:
  python3 score.py --model DIR --split NAME --out FILE.json [--batch 16]
  python3 score.py --model DIR --inspect
  NAME in {diagnostic, validation, heldout, forget_instr, forget_fact,
           forget_prose, all}

Behaviour:
  - loads the model with transformers in bf16, on cuda if available else cpu;
  - prompts go through the tokenizer's chat template with thinking disabled
    (Qwen3: apply_chat_template(..., enable_thinking=False); guarded with a
    fallback for APIs that do not accept the kwarg);
  - greedy decoding only (do_sample=False), fixed batch size, items processed
    in file order — no sampling anywhere;
  - per-split max_new_tokens: arithmetic 96, forget_instr 128, forget_fact 32;
  - arithmetic: extract the LAST number in the completion (after stripping
    $, %, and thousands commas); integer golds must match exactly, money
    golds within abs tolerance 0.011;
  - forget_instr: run the item's checker (definitions below, mirroring
    BATTERIES.md exactly);
  - forget_fact: normalised containment — reply matches if the answer or any
    alias appears in the reply as a whole token span after normalisation
    (casefold, accents stripped, punctuation → spaces, commas removed);
  - forget_prose: mean token NLL of the raw paragraph text, teacher-forced,
    no generation, no chat template (a pure LM-likelihood drift measure).

Output JSON (deterministic — no timestamps, no sampling):
  {model, split, n_items, metric, overall, per_category, items:[...]}
  per-item: {id, category, gold, raw_output, extracted, correct} (prose adds
  "nll" and leaves gold/raw_output/extracted/correct null). --split all wraps
  the same blocks under "splits".

Only torch/transformers beyond the stdlib.
"""

import argparse
import json
import re
import sys
import unicodedata
from pathlib import Path

import torch
from transformers import AutoModelForCausalLM, AutoTokenizer

HERE = Path(__file__).resolve().parent

SPLIT_FILES = {
    "diagnostic": "batteries/diagnostic.jsonl",
    "validation": "batteries/validation.jsonl",
    "heldout": "private/heldout.jsonl",
    "forget_instr": "private/forget_instr.jsonl",
    "forget_fact": "private/forget_fact.jsonl",
    "forget_prose": "private/forget_prose.jsonl",
}
SPLIT_ORDER = ["diagnostic", "validation", "heldout",
               "forget_instr", "forget_fact", "forget_prose"]
ARITH_SPLITS = {"diagnostic", "validation", "heldout"}

MAX_NEW_TOKENS = {"diagnostic": 96, "validation": 96, "heldout": 96,
                  "forget_instr": 128, "forget_fact": 32}
MONEY_TOL = 0.011


def load_jsonl(path):
    rows = []
    with path.open(encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if line:
                rows.append(json.loads(line))
    return rows


# --------------------------------------------------------------------------
# Model + prompt plumbing
# --------------------------------------------------------------------------

def load_model(model_dir):
    tokenizer = AutoTokenizer.from_pretrained(model_dir)
    try:
        model = AutoModelForCausalLM.from_pretrained(model_dir,
                                                     torch_dtype=torch.bfloat16)
    except TypeError:  # older/newer transformers kwarg naming
        model = AutoModelForCausalLM.from_pretrained(model_dir)
    device = "cuda" if torch.cuda.is_available() else "cpu"
    model.to(device)
    model.eval()
    return tokenizer, model


def build_prompt(tokenizer, text):
    messages = [{"role": "user", "content": text}]
    try:
        return tokenizer.apply_chat_template(
            messages, tokenize=False, add_generation_prompt=True,
            enable_thinking=False)
    except TypeError:  # template API without the thinking kwarg
        return tokenizer.apply_chat_template(
            messages, tokenize=False, add_generation_prompt=True)


@torch.no_grad()
def generate_batched(model, tokenizer, prompts, max_new_tokens, batch_size):
    """Greedy generation, items in order, left padding. Deterministic."""
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token
    tokenizer.padding_side = "left"
    outputs = []
    for start in range(0, len(prompts), batch_size):
        chunk = prompts[start:start + batch_size]
        enc = tokenizer(chunk, return_tensors="pt", padding=True).to(model.device)
        out = model.generate(**enc, max_new_tokens=max_new_tokens,
                             do_sample=False)
        gen = out[:, enc["input_ids"].shape[1]:]
        outputs.extend(tokenizer.batch_decode(gen, skip_special_tokens=True))
        print(f"    {min(start + len(chunk), len(prompts))}/{len(prompts)}",
              flush=True)
    return outputs


# --------------------------------------------------------------------------
# Arithmetic scoring
# --------------------------------------------------------------------------

_NUMBER_RE = re.compile(r"-?\d+(?:\.\d+)?")


def extract_number(text):
    cleaned = (text.replace(",", "").replace("$", "")
                    .replace("%", "").replace("€", "").replace("£", ""))
    nums = _NUMBER_RE.findall(cleaned)
    return float(nums[-1]) if nums else None


def arith_correct(gold, extracted):
    if extracted is None:
        return False
    if float(gold).is_integer():
        return extracted == float(gold)
    return abs(extracted - float(gold)) <= MONEY_TOL


# --------------------------------------------------------------------------
# forget_instr checkers (definitions mirrored in BATTERIES.md)
# --------------------------------------------------------------------------

_TRAILING_PUNCT = ".,!?:;\"')"


def check_json_key(reply, key):
    t = reply.strip()
    if t.startswith("```"):
        t = re.sub(r"^```[A-Za-z0-9]*\s*", "", t)
        t = re.sub(r"\s*```$", "", t).strip()
    try:
        obj = json.loads(t)
    except (json.JSONDecodeError, ValueError):
        return False
    return isinstance(obj, dict) and key in obj


def check_all_caps(reply):
    t = reply.strip()
    letters = [c for c in t if c.isalpha()]
    return bool(letters) and t == t.upper()


def check_starts_with(reply, word):
    return reply.strip().lower().startswith(word.strip().lower())


def check_ends_with(reply, word):
    t = reply.strip().lower()
    while t and t[-1] in _TRAILING_PUNCT:
        t = t[:-1]
    return t.endswith(word.strip().lower())


def check_bullets3(reply):
    lines = [ln for ln in reply.strip().splitlines() if ln.strip()]
    dashes = [ln for ln in lines if ln.lstrip().startswith("- ")]
    return len(dashes) == 3


def check_word_count_range(reply, lo, hi):
    return lo <= len(reply.split()) <= hi


def run_check(check, reply):
    t = check["type"]
    if t == "json_key":
        return check_json_key(reply, check["key"])
    if t == "all_caps":
        return check_all_caps(reply)
    if t == "starts_with":
        return check_starts_with(reply, check["word"])
    if t == "ends_with":
        return check_ends_with(reply, check["word"])
    if t == "bullets3":
        return check_bullets3(reply)
    if t == "word_count_range":
        return check_word_count_range(reply, check["lo"], check["hi"])
    raise ValueError(f"unknown check type: {t}")


# --------------------------------------------------------------------------
# forget_fact scoring
# --------------------------------------------------------------------------

def norm_text(s):
    s = s.replace(",", "")  # keep "100,000" == "100000"
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    s = re.sub(r"[^0-9a-z]+", " ", s.lower())
    return " ".join(s.split())


def fact_correct(reply, answer, aliases):
    norm_reply = norm_text(reply)
    for gold in [answer] + list(aliases):
        g = norm_text(gold)
        if not g:
            continue
        if re.search(r"(?<!\w)" + re.escape(g) + r"(?!\w)", norm_reply):
            return True
    return False


# --------------------------------------------------------------------------
# forget_prose scoring: mean token NLL, teacher-forced, no chat template
# --------------------------------------------------------------------------

@torch.no_grad()
def prose_nll(model, tokenizer, texts, batch_size=8):
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token
    tokenizer.padding_side = "right"
    nlls = []
    for start in range(0, len(texts), batch_size):
        chunk = texts[start:start + batch_size]
        enc = tokenizer(chunk, return_tensors="pt", padding=True).to(model.device)
        input_ids = enc["input_ids"]
        labels = input_ids.clone()
        labels[enc["attention_mask"] == 0] = -100
        logits = model(**enc).logits.float()
        shift_logits = logits[:, :-1, :]
        shift_labels = labels[:, 1:]
        loss_fct = torch.nn.CrossEntropyLoss(reduction="none",
                                             ignore_index=-100)
        losses = loss_fct(
            shift_logits.reshape(-1, shift_logits.size(-1)),
            shift_labels.reshape(-1)).view(shift_labels.shape)
        token_counts = (shift_labels != -100).sum(dim=1).clamp(min=1)
        nlls.extend((losses.sum(dim=1) / token_counts).tolist())
        print(f"    {min(start + len(chunk), len(texts))}/{len(texts)}",
              flush=True)
    return nlls


# --------------------------------------------------------------------------
# Split scoring
# --------------------------------------------------------------------------

def aggregate(items, key_name, correct_name="correct"):
    per_cat = {}
    vals = [it[correct_name] for it in items]
    for it in items:
        cat = it["category"]
        per_cat.setdefault(cat, []).append(it[correct_name])
    return {
        key_name: (sum(vals) / len(vals)) if vals else None,
        "per_category": {cat: {"n": len(v), key_name: (sum(v) / len(v))}
                         for cat, v in sorted(per_cat.items())},
    }


def score_split(model, tokenizer, split, batch_size):
    items = load_jsonl(HERE / SPLIT_FILES[split])
    print(f"  [{split}] {len(items)} items", flush=True)
    block = {"split": split, "n_items": len(items)}

    if split in ARITH_SPLITS:
        raw = generate_batched(model, tokenizer,
                               [it["prompt"] for it in items],
                               MAX_NEW_TOKENS[split], batch_size)
        records = []
        for it, out in zip(items, raw):
            extracted = extract_number(out)
            records.append({
                "id": it["id"], "category": it["category"],
                "gold": it["answer"], "raw_output": out,
                "extracted": extracted,
                "correct": arith_correct(it["answer"], extracted),
            })
        block["metric"] = "accuracy"
        block.update(aggregate(records, "accuracy"))
        block["items"] = records

    elif split == "forget_instr":
        raw = generate_batched(model, tokenizer,
                               [it["prompt"] for it in items],
                               MAX_NEW_TOKENS[split], batch_size)
        records = []
        for it, out in zip(items, raw):
            records.append({
                "id": it["id"], "category": it["category"],
                "gold": it["check"], "raw_output": out,
                "extracted": None, "correct": run_check(it["check"], out),
            })
        block["metric"] = "accuracy"
        block.update(aggregate(records, "accuracy"))
        block["items"] = records

    elif split == "forget_fact":
        raw = generate_batched(model, tokenizer,
                               [it["prompt"] for it in items],
                               MAX_NEW_TOKENS[split], batch_size)
        records = []
        for it, out in zip(items, raw):
            records.append({
                "id": it["id"], "category": it["category"],
                "gold": it["answer"], "raw_output": out,
                "extracted": None,
                "correct": fact_correct(out, it["answer"], it["aliases"]),
            })
        block["metric"] = "accuracy"
        block.update(aggregate(records, "accuracy"))
        block["items"] = records

    elif split == "forget_prose":
        nlls = prose_nll(model, tokenizer,
                         [it["text"] for it in items], batch_size)
        records = []
        for it, nll in zip(items, nlls):
            records.append({
                "id": it["id"], "category": "prose",
                "gold": None, "raw_output": None, "extracted": None,
                "correct": None, "nll": nll,
            })
        block["metric"] = "mean_nll"
        block["mean_nll"] = sum(nlls) / len(nlls)
        block["per_category"] = {"prose": {"n": len(nlls),
                                           "mean_nll": block["mean_nll"]}}
        block["items"] = records

    else:
        raise ValueError(f"unknown split: {split}")
    return block


def inspect(model_dir):
    tokenizer, model = load_model(model_dir)
    cfg = model.config
    info = {
        "model_dir": str(model_dir),
        "model_type": getattr(cfg, "model_type", None),
        "num_hidden_layers": getattr(cfg, "num_hidden_layers", None),
        "hidden_size": getattr(cfg, "hidden_size", None),
        "intermediate_size": getattr(cfg, "intermediate_size", None),
        "num_attention_heads": getattr(cfg, "num_attention_heads", None),
        "vocab_size": getattr(cfg, "vocab_size", None),
        "tie_word_embeddings": bool(getattr(cfg, "tie_word_embeddings", False)),
        "num_parameters": sum(p.numel() for p in model.parameters()),
        "parameter_dtypes": sorted({str(p.dtype) for p in model.parameters()}),
        "device": str(next(model.parameters()).device),
        "tokenizer_vocab_size": len(tokenizer),
    }
    print(json.dumps(info, indent=2))


def main():
    ap = argparse.ArgumentParser(description="Phase 15 WSP battery scorer")
    ap.add_argument("--model", required=True, help="model directory")
    ap.add_argument("--split", default=None,
                    choices=list(SPLIT_FILES) + ["all"])
    ap.add_argument("--out", default=None, help="output JSON path")
    ap.add_argument("--batch", type=int, default=16,
                    help="generation batch size (default 16)")
    ap.add_argument("--inspect", action="store_true",
                    help="print model config summary as JSON and exit")
    args = ap.parse_args()

    if not args.split and not args.inspect:
        ap.error("nothing to do: give --split and/or --inspect")

    if args.inspect:
        inspect(args.model)
        if not args.split:
            return

    tokenizer, model = load_model(args.model)

    if args.split == "all":
        result = {"model": args.model,
                  "splits": {s: score_split(model, tokenizer, s, args.batch)
                             for s in SPLIT_ORDER}}
        for s, block in result["splits"].items():
            head = block["accuracy"] if block["metric"] == "accuracy" \
                else block["mean_nll"]
            print(f"  summary {s}: {block['metric']} = {head}")
    else:
        result = score_split(model, tokenizer, args.split, args.batch)
        result["model"] = args.model
        head = result["accuracy"] if result["metric"] == "accuracy" \
            else result["mean_nll"]
        print(f"  summary {args.split}: {result['metric']} = {head}")

    if args.out:
        out_path = Path(args.out)
        out_path.parent.mkdir(parents=True, exist_ok=True)
        with out_path.open("w", encoding="utf-8") as fh:
            json.dump(result, fh, indent=2, ensure_ascii=False)
        print(f"  wrote {args.out}")


if __name__ == "__main__":
    main()
